curl -s -A "Mozilla/5.0 research agent contact@example.com" "https://www.sec.gov/Archives/edgar/data/320193/000032019326000013/aapl-20260328.htm" | python3 << 'EOF'
import sys, re

content = sys.stdin.read()

# Remove ix: tags but keep content
content2 = re.sub(r'<ix:[^>]+>', '', content)
content2 = re.sub(r'</ix:[^>]+>', '', content2)

def clean_html(s):
    s = re.sub(r'<[^>]+>', ' ', s)
    for entity, char in [('&amp;', '&'), ('&nbsp;', ' '), ('&#160;', ' '), ('&#8209;', '-'), ('&#8212;', '—')]:
        s = s.replace(entity, char)
    s = re.sub(r'&#[0-9]+;', ' ', s)
    s = re.sub(r'\s+', ' ', s)
    return s

# Find all major financial statements
sections = [
    'condensed consolidated statements of operations',
    'condensed consolidated balance sheet',
    'condensed consolidated statements of cash flows',
]

for section in sections:
    idx = content2.lower().find(section)
    if idx >= 0:
        snippet = content2[idx:idx+25000]
        clean = clean_html(snippet)
        # Find end of section
        next_section_idx = None
        for other in sections:
            if other != section:
                end = clean.lower().find(other)
                if end > 100:
                    if next_section_idx is None or end < next_section_idx:
                        next_section_idx = end

        if next_section_idx:
            print(f"\n=== {section.upper()} ===")
            print(clean[:next_section_idx])
        else:
            print(f"\n=== {section.upper()} ===")
            print(clean[:5000])
EOF

